const topicId = Math.max(1, Math.floor(Number(input.topicId) || 0));
const limit = Math.max(1, Math.min(Number(input.limit) || 15, 30));
const origin = typeof location !== 'undefined' && typeof location.origin === 'string' && /^https:\/\/(?:www\.)?v2ex\.com$/i.test(location.origin) ? location.origin : '';
if (!origin) {
  return { success: false, status: 'page_not_ready', topicId, message: 'V2EX page origin is not ready', source: 'https://www.v2ex.com/t/' + topicId };
}
const topicUrl = new URL('/api/topics/show.json?id=' + topicId, origin).href;
const repliesUrl = new URL('/api/replies/show.json?topic_id=' + topicId + '&page=1', origin).href;
let topicRes;
let repliesRes;
try {
  [topicRes, repliesRes] = await Promise.all([
    fetch(topicUrl, { credentials: 'include', headers: { Accept: 'application/json' } }),
    fetch(repliesUrl, { credentials: 'include', headers: { Accept: 'application/json' } })
  ]);
} catch (error) {
  return { success: false, status: 'fetch_error', topicId, message: String(error && error.message || error), source: topicUrl };
}
if (topicRes.status === 403 || repliesRes.status === 403) {
  const blocked = topicRes.status === 403 ? topicRes : repliesRes;
  return { success: false, status: 'requires_auth', topicId, requiresLogin: true, httpStatus: 403, message: 'V2EX topic requires authentication or is restricted', source: blocked.url || topicUrl };
}
if (topicRes.status === 429 || repliesRes.status === 429) {
  const limited = topicRes.status === 429 ? topicRes : repliesRes;
  return { success: false, status: 'rate_limited', topicId, httpStatus: 429, source: limited.url || topicUrl };
}
if (topicRes.status === 404 || repliesRes.status === 404) {
  const missing = topicRes.status === 404 ? topicRes : repliesRes;
  return { success: false, status: 'not_found', topicId, httpStatus: 404, source: missing.url || topicUrl };
}
if (!topicRes.ok) {
  return { success: false, status: 'http_error', topicId, httpStatus: topicRes.status, source: topicRes.url || topicUrl };
}
if (!repliesRes.ok) {
  return { success: false, status: 'http_error', topicId, httpStatus: repliesRes.status, source: repliesRes.url || repliesUrl };
}
let topicList;
let replyList;
try {
  topicList = await topicRes.json();
  replyList = await repliesRes.json();
} catch {
  return { success: false, status: 'invalid_json', topicId, source: topicRes.url || topicUrl };
}
if (!Array.isArray(topicList) || !Array.isArray(replyList)) {
  return { success: false, status: 'schema_changed', topicId, source: topicRes.url || topicUrl };
}
if (topicList.length === 0) {
  return { success: false, status: 'not_found', topicId, source: topicRes.url || topicUrl };
}
const item = topicList[0];
const id = Math.floor(Number(item && item.id) || 0);
const title = String((item && item.title) || '').trim();
const page = String((item && item.url) || (id > 0 ? 'https://www.v2ex.com/t/' + id : '')).trim();
if (!id || !title || !/^https:\/\/(?:www\.)?v2ex\.com\/t\/\d+/.test(page)) {
  return { success: false, status: 'schema_changed', topicId, source: topicRes.url || topicUrl };
}
const replies = replyList
  .map(reply => ({
    id: Math.floor(Number(reply && reply.id) || 0),
    author: String((reply && reply.member && reply.member.username) || '').trim(),
    created: Math.max(0, Math.floor(Number(reply && reply.created) || 0)),
    content: String((reply && reply.content) || '').trim().slice(0, 1500)
  }))
  .filter(reply => reply.id > 0)
  .slice(0, limit);
return {
  success: true,
  status: 'ok',
  coverage: 'first_page_only',
  topic: {
    id,
    title,
    url: page,
    node: String((item && item.node && item.node.name) || '').trim(),
    nodeTitle: String((item && item.node && item.node.title) || '').trim(),
    author: String((item && item.member && item.member.username) || '').trim(),
    repliesCount: Math.max(replies.length, Math.floor(Number(item && item.replies) || 0)),
    created: Math.max(0, Math.floor(Number(item && item.created) || 0)),
    content: String((item && item.content) || '').trim().slice(0, 6000)
  },
  replies,
  sources: {
    api: topicRes.url || topicUrl,
    repliesApi: repliesRes.url || repliesUrl,
    page
  }
};
